import { BetSlip } from "@/components/bet-slip";

export default function Page() {
  return (
    <div className="flex min-h-svh items-start justify-center bg-background p-6">
      <BetSlip />
    </div>
  );
}

/**
 * The arithmetic of a bet slip, kept out of the UI so it can be tested.
 * Money is held in integer minor units (cents) so totals never pick up
 * floating-point drift; odds are decimal.
 */

export interface Selection {
  /** The odds the punter last accepted. Differs from `odds` after a move. */
  acceptedOdds: number;
  event: string;
  id: string;
  market: string;
  odds: number;
  pick: string;
}

export type SlipMode = "accumulator" | "singles";

/** Parse a stake typed by the punter into cents; anything invalid is 0. */
export function parseStake(input: string): number {
  const value = Number(input.replace(",", "."));
  if (!Number.isFinite(value) || value <= 0) {
    return 0;
  }
  return Math.round(value * 100);
}

/** Combined decimal odds of an accumulator: the product of every leg. */
export function accumulatorOdds(selections: readonly Selection[]): number {
  return selections.reduce((product, s) => product * s.odds, 1);
}

/** Total staked and total potential return, both in cents. */
export function slipTotals(
  selections: readonly Selection[],
  stakes: Readonly<Record<string, number>>,
  mode: SlipMode,
  accumulatorStake: number
): { stake: number; potentialReturn: number } {
  if (mode === "accumulator") {
    if (selections.length < 2) {
      return { potentialReturn: 0, stake: 0 };
    }
    return {
      potentialReturn: Math.floor(
        accumulatorStake * accumulatorOdds(selections)
      ),
      stake: accumulatorStake,
    };
  }
  let stake = 0;
  let potentialReturn = 0;
  for (const s of selections) {
    const cents = stakes[s.id] ?? 0;
    stake += cents;
    potentialReturn += Math.floor(cents * s.odds);
  }
  return { potentialReturn, stake };
}

/** Selections whose price moved since the punter last accepted it. */
export function changedSelections(
  selections: readonly Selection[]
): Selection[] {
  return selections.filter((s) => s.odds !== s.acceptedOdds);
}

export type BlockReason = "empty" | "odds-changed" | "over-limit" | "no-stake";

/**
 * Why the slip cannot be placed, if it cannot. Order matters: the first
 * reason is the one the button explains.
 */
export function blockReason(
  selections: readonly Selection[],
  totalStake: number,
  remainingLimit: number
): BlockReason | null {
  if (selections.length === 0) {
    return "empty";
  }
  if (totalStake === 0) {
    return "no-stake";
  }
  if (totalStake > remainingLimit) {
    return "over-limit";
  }
  if (changedSelections(selections).length > 0) {
    return "odds-changed";
  }
  return null;
}

export function formatMoney(cents: number, currency = "EUR"): string {
  return new Intl.NumberFormat("en-IE", {
    currency,
    style: "currency",
  }).format(cents / 100);
}

export function formatOdds(odds: number): string {
  return odds.toFixed(2);
}

"use client";

import {
  ArrowDownIcon,
  ArrowUpIcon,
  ShieldAlertIcon,
  XIcon,
} from "lucide-react";
import { useCallback, useMemo, useState } from "react";
import {
  accumulatorOdds,
  type BlockReason,
  blockReason,
  changedSelections,
  formatMoney,
  formatOdds,
  parseStake,
  type Selection,
  type SlipMode,
  slipTotals,
} from "@/components/bet-slip-math";
import {
  DAILY_LIMIT,
  INITIAL_SELECTIONS,
  STAKED_TODAY,
} from "@/components/mock-selections";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardAction,
  CardContent,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyTitle,
} from "@/components/ui/empty";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
  InputGroupText,
} from "@/components/ui/input-group";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useOddsFeed } from "@/components/use-odds-feed";

const BUTTON_LABEL: Record<BlockReason, string> = {
  empty: "Add a selection",
  "no-stake": "Enter a stake",
  "odds-changed": "Accept odds changes",
  "over-limit": "Over your daily limit",
};

function OddsMovement({ selection }: { selection: Selection }) {
  if (selection.odds === selection.acceptedOdds) {
    return null;
  }
  const up = selection.odds > selection.acceptedOdds;
  const Icon = up ? ArrowUpIcon : ArrowDownIcon;
  return (
    <span
      className={up ? "text-success" : "text-destructive"}
      data-slot="odds-movement"
    >
      <Icon aria-hidden className="size-3.5" />
      <span className="sr-only">
        {up ? "Odds lengthened" : "Odds shortened"} from{" "}
        {formatOdds(selection.acceptedOdds)}
      </span>
    </span>
  );
}

function StakeInput({
  label,
  onChange,
  value,
}: {
  label: string;
  onChange: (value: string) => void;
  value: string;
}) {
  return (
    <InputGroup size="sm">
      <InputGroupAddon>
        <InputGroupText>€</InputGroupText>
      </InputGroupAddon>
      <InputGroupInput
        aria-label={label}
        inputMode="decimal"
        onChange={(event) => onChange(event.target.value)}
        placeholder="0.00"
        value={value}
      />
    </InputGroup>
  );
}

export function BetSlip({ liveOdds = true }: { liveOdds?: boolean }) {
  const [selections, setSelections] = useState(INITIAL_SELECTIONS);
  const [mode, setMode] = useState<SlipMode>("singles");
  const [stakeInputs, setStakeInputs] = useState<Record<string, string>>({
    "sel-1": "10",
  });
  const [accumulatorInput, setAccumulatorInput] = useState("");
  const [placed, setPlaced] = useState(false);

  const stableSetSelections = useCallback(
    (update: (prev: Selection[]) => Selection[]) => setSelections(update),
    []
  );
  useOddsFeed(stableSetSelections, { enabled: liveOdds && !placed });

  const stakes = useMemo(
    () =>
      Object.fromEntries(
        Object.entries(stakeInputs).map(([id, input]) => [
          id,
          parseStake(input),
        ])
      ),
    [stakeInputs]
  );
  // An accumulator needs two legs. Below that the tab is disabled, and a
  // slip left on it would have no stake input at all.
  const activeMode: SlipMode = selections.length < 2 ? "singles" : mode;
  const totals = slipTotals(
    selections,
    stakes,
    activeMode,
    parseStake(accumulatorInput)
  );
  const remaining = DAILY_LIMIT - STAKED_TODAY;
  const reason = blockReason(selections, totals.stake, remaining);
  const changed = changedSelections(selections);

  const acceptChanges = () =>
    setSelections((prev) => prev.map((s) => ({ ...s, acceptedOdds: s.odds })));
  const remove = (id: string) =>
    setSelections((prev) => prev.filter((s) => s.id !== id));

  if (placed) {
    return (
      <Card className="w-full max-w-sm">
        <CardContent>
          <Empty>
            <EmptyHeader>
              <EmptyTitle>Bet placed</EmptyTitle>
              <EmptyDescription>
                {formatMoney(totals.stake)} staked to return up to{" "}
                {formatMoney(totals.potentialReturn)}.
              </EmptyDescription>
            </EmptyHeader>
          </Empty>
        </CardContent>
        <CardFooter>
          <Button
            className="w-full"
            onClick={() => {
              setPlaced(false);
              setSelections(INITIAL_SELECTIONS);
            }}
            variant="secondary"
          >
            New slip
          </Button>
        </CardFooter>
      </Card>
    );
  }

  return (
    <Card className="w-full max-w-sm" data-slot="bet-slip">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          Bet slip
          <Badge variant="secondary">{selections.length}</Badge>
        </CardTitle>
        {selections.length > 0 && (
          <CardAction>
            <Button onClick={() => setSelections([])} size="sm" variant="ghost">
              Clear
            </Button>
          </CardAction>
        )}
      </CardHeader>

      <CardContent className="flex flex-col gap-4">
        <Tabs
          onValueChange={(value) => setMode(value as SlipMode)}
          value={activeMode}
        >
          <TabsList className="w-full">
            <TabsTrigger value="singles">Singles</TabsTrigger>
            <TabsTrigger disabled={selections.length < 2} value="accumulator">
              Accumulator
            </TabsTrigger>
          </TabsList>
        </Tabs>

        {selections.length === 0 ? (
          <Empty>
            <EmptyHeader>
              <EmptyTitle>Your slip is empty</EmptyTitle>
              <EmptyDescription>
                Pick a price to add a selection.
              </EmptyDescription>
            </EmptyHeader>
          </Empty>
        ) : (
          <ul className="flex flex-col divide-y divide-border">
            {selections.map((s) => (
              <li className="flex flex-col gap-2 py-3 first:pt-0" key={s.id}>
                <div className="flex items-start gap-2">
                  <div className="min-w-0 flex-1">
                    <p className="font-medium text-sm">{s.pick}</p>
                    <p className="text-muted-foreground text-xs">
                      {s.market} · {s.event}
                    </p>
                  </div>
                  <span className="flex items-center gap-1 font-semibold text-sm tabular-nums">
                    <OddsMovement selection={s} />
                    {formatOdds(s.odds)}
                  </span>
                  <Button
                    aria-label={`Remove ${s.pick}`}
                    onClick={() => remove(s.id)}
                    size="icon-xs"
                    variant="ghost"
                  >
                    <XIcon />
                  </Button>
                </div>
                {activeMode === "singles" && (
                  <div className="flex items-center gap-3">
                    <StakeInput
                      label={`Stake on ${s.pick}`}
                      onChange={(value) =>
                        setStakeInputs((prev) => ({ ...prev, [s.id]: value }))
                      }
                      value={stakeInputs[s.id] ?? ""}
                    />
                    <span className="shrink-0 text-muted-foreground text-xs tabular-nums">
                      Returns{" "}
                      {formatMoney(Math.floor((stakes[s.id] ?? 0) * s.odds))}
                    </span>
                  </div>
                )}
              </li>
            ))}
          </ul>
        )}

        {activeMode === "accumulator" && (
          <div className="flex items-center gap-3">
            <StakeInput
              label="Accumulator stake"
              onChange={setAccumulatorInput}
              value={accumulatorInput}
            />
            <span className="shrink-0 text-muted-foreground text-xs tabular-nums">
              {selections.length}-fold @{" "}
              {formatOdds(accumulatorOdds(selections))}
            </span>
          </div>
        )}

        {changed.length > 0 && (
          <Alert variant="warning">
            <AlertTitle>Odds have changed</AlertTitle>
            <AlertDescription>
              {changed.length === 1
                ? `${changed[0].pick} moved from ${formatOdds(changed[0].acceptedOdds)} to ${formatOdds(changed[0].odds)}.`
                : `${changed.length} prices moved since you added them.`}
            </AlertDescription>
          </Alert>
        )}

        {reason === "over-limit" && (
          <Alert variant="error">
            <ShieldAlertIcon />
            <AlertTitle>Over your daily limit</AlertTitle>
            <AlertDescription>
              You can stake {formatMoney(remaining)} more today. Lower your
              stake, or review your limits in Responsible Gambling.
            </AlertDescription>
          </Alert>
        )}
      </CardContent>

      <CardFooter className="flex flex-col gap-3">
        <dl className="grid w-full grid-cols-2 gap-y-1 text-sm">
          <dt className="text-muted-foreground">Total stake</dt>
          <dd className="text-end tabular-nums">{formatMoney(totals.stake)}</dd>
          <dt className="text-muted-foreground">Potential return</dt>
          <dd className="text-end font-semibold tabular-nums">
            {formatMoney(totals.potentialReturn)}
          </dd>
        </dl>
        {reason === "odds-changed" ? (
          <Button className="w-full" onClick={acceptChanges}>
            Accept odds changes
          </Button>
        ) : (
          <Button
            className="w-full"
            disabled={reason !== null}
            onClick={() => setPlaced(true)}
          >
            {reason
              ? BUTTON_LABEL[reason]
              : `Place bet · ${formatMoney(totals.stake)}`}
          </Button>
        )}
        <p className="text-center text-muted-foreground text-xs">
          Daily limit {formatMoney(DAILY_LIMIT)} · {formatMoney(remaining)} left
          today
        </p>
      </CardFooter>
    </Card>
  );
}

import type { Selection } from "@/components/bet-slip-math";

export const INITIAL_SELECTIONS: Selection[] = [
  {
    acceptedOdds: 2.1,
    event: "Arsenal v Chelsea",
    id: "sel-1",
    market: "Match result",
    odds: 2.1,
    pick: "Arsenal",
  },
  {
    acceptedOdds: 1.85,
    event: "Real Madrid v Sevilla",
    id: "sel-2",
    market: "Total goals",
    odds: 1.85,
    pick: "Over 2.5",
  },
  {
    acceptedOdds: 3.4,
    event: "Lakers v Celtics",
    id: "sel-3",
    market: "Winner",
    odds: 3.4,
    pick: "Celtics",
  },
];

/** What the account's responsible-gambling settings allow today, in cents. */
export const DAILY_LIMIT = 10_000;
export const STAKED_TODAY = 6000;

import { useEffect } from "react";

import type { Selection } from "@/components/bet-slip-math";

/**
 * A stand-in for a live price feed: every `interval` ms one selection's odds
 * drift by a tick. Replace with your feed's subscription.
 */
export function useOddsFeed(
  setSelections: (update: (prev: Selection[]) => Selection[]) => void,
  { enabled, interval = 6000 }: { enabled: boolean; interval?: number }
) {
  useEffect(() => {
    if (!enabled) {
      return;
    }
    let tick = 0;
    const id = setInterval(() => {
      tick += 1;
      setSelections((prev) => {
        if (prev.length === 0) {
          return prev;
        }
        const target = tick % prev.length;
        const direction = tick % 3 === 0 ? -1 : 1;
        return prev.map((s, i) =>
          i === target
            ? {
                ...s,
                odds: Math.max(
                  1.01,
                  Number((s.odds + direction * 0.05).toFixed(2))
                ),
              }
            : s
        );
      });
    }, interval);
    return () => clearInterval(id);
  }, [enabled, interval, setSelections]);
}
